function longestPrefix(s) {
  const lps = new Array(s.length).fill(0);
  let length = 0;

  for (let i = 1; i < s.length; i++) {
    while (length > 0 && s[i] !== s[length]) {
      length = lps[length - 1];
    }
    if (s[i] === s[length]) {
      length++;
    }
    lps[i] = length;
  }
  return s.slice(0, length);
}

