function longestPrefix(s) {
  // Try every proper length from the longest down and compare the two ends directly.
  for (let size = s.length - 1; size >= 1; size--) {
    let same = true;
    for (let k = 0; k < size && same; k++) if (s.charCodeAt(k) !== s.charCodeAt(s.length - size + k)) same = false;
    if (same) return s.substring(0, size);
  }
  return '';
}

