function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const word = (len, alpha) => Array.from({ length: len }, () => letters[int(0, alpha - 1)]).join('');
  const limit = size === 'large' ? 10000 : 12;
  const n = size === 'large' ? int(8000, 10000) : int(1, limit);
  const pick = rand();
  let s;
  if (pick < 0.3) s = word(n, int(1, 3));
  else if (pick < 0.6) {
    // A repeated block, often with one changed letter, gives long borders and many fallbacks.
    const block = word(int(1, size === 'large' ? 40 : 4), int(1, 3));
    s = block.repeat(Math.ceil(n / block.length)).slice(0, n);
    if (rand() < 0.5) { const at = int(0, n - 1); s = s.slice(0, at) + letters[int(0, 3)] + s.slice(at + 1); }
  } else if (pick < 0.8) {
    // Same piece at both ends with something in between.
    const piece = word(int(1, Math.max(1, Math.floor(n / 3))), int(1, 3));
    s = (piece + word(Math.max(0, n - 2 * piece.length), int(1, 26)) + piece).slice(0, limit);
  } else s = word(n, 26);
  return [s];
}
